<?php
declare(strict_types=1);

namespace wise\agent\schema\params;

/**
 * 工具参数 DTO
 *
 * 存储单个 AI Tool 的 JSON Schema 参数定义。
 * 由 ParamBuilder 构建，用于 AutoGeneratedTool::getParameters()。
 */
class ToolParams implements \JsonSerializable
{
    /** @var string 工具名称 */
    public $toolName = '';

    /** @var string 工具类型：list|get|search|stats|create|update|delete|list_with_relation */
    public $toolType = '';

    /** @var string 目标表名 */
    public $tableName = '';

    /** @var string 插件标识 */
    public $pluginIdent = '';

    /** @var array 关联关系名（仅 list_with_relation 类型） */
    public $relationName = '';

    /** @var array JSON Schema 参数定义 */
    public $parameters = [];

    /** @var array 必填参数列表 */
    public $required = [];

    /**
     * @param string $toolName 工具名称
     * @param string $toolType 工具类型
     * @param string $tableName 目标表名
     * @param string $pluginIdent 插件标识
     */
    public function __construct(
        string $toolName = '',
        string $toolType = '',
        string $tableName = '',
        string $pluginIdent = ''
    ) {
        $this->toolName    = $toolName;
        $this->toolType    = $toolType;
        $this->tableName   = $tableName;
        $this->pluginIdent = $pluginIdent;
    }

    /**
     * 添加参数定义
     *
     * @param string $name 参数名
     * @param array $schema JSON Schema 片段
     * @param bool $required 是否必填
     * @return $this
     */
    public function addParam(string $name, array $schema, bool $required = false): self
    {
        $this->parameters[$name] = $schema;
        if ($required) {
            $this->required[] = $name;
        }
        return $this;
    }

    /**
     * 获取完整的 JSON Schema 参数定义
     *
     * @return array
     */
    public function toJsonSchema(): array
    {
        $schema = [
            'type'       => 'object',
            'properties' => $this->parameters,
        ];

        if (!empty($this->required)) {
            $schema['required'] = $this->required;
        }

        return $schema;
    }

    /**
     * 转为数组
     *
     * @return array
     */
    public function toArray(): array
    {
        return [
            'tool_name'     => $this->toolName,
            'tool_type'     => $this->toolType,
            'table_name'    => $this->tableName,
            'plugin_ident'  => $this->pluginIdent,
            'relation_name' => $this->relationName,
            'parameters'    => $this->parameters,
            'required'      => $this->required,
        ];
    }

    /**
     * 从数组构造
     *
     * @param array $data
     * @return self
     */
    public static function fromArray(array $data): self
    {
        $params = new self(
            $data['tool_name'] ?? '',
            $data['tool_type'] ?? '',
            $data['table_name'] ?? '',
            $data['plugin_ident'] ?? ''
        );
        $params->relationName = $data['relation_name'] ?? '';
        $params->parameters   = $data['parameters'] ?? [];
        $params->required     = $data['required'] ?? [];
        return $params;
    }

    /**
     * JSON 序列化
     */
    #[\ReturnTypeWillChange]
    public function jsonSerialize()
    {
        return $this->toArray();
    }
}
